LESSONS.forEach((l, i) => { l.n = i + 1; });

export const trackOf = l => TRACKS.find(t => t.n === l.track);
export const groupOf = l => trackOf(l)?.group || 'clay';
export const LIVE = LESSONS.filter(l => l.live);

// a track can be certified once it is fully built and every lesson in it is done
export const certifiable = (tr, done) => { const ls = LIVE.filter(l => l.track === tr.n); return !!tr.size && ls.length >= tr.size && ls.every(l => done.has(l.slug)); };
